"""Reservation service (REQ-001, REQ-002)."""


class ReservationError(Exception):
    pass


class ReservationService:
    def __init__(self) -> None:
        self._active: dict[str, str] = {}
        self._blocked: set[str] = set()

    def reserve(self, copy_id: str, member_id: str) -> None:
        if copy_id in self._active or copy_id in self._blocked:
            raise ReservationError(f"copy {copy_id} already reserved")
        self._active[copy_id] = member_id

    def cancel(self, copy_id: str, member_id: str) -> None:
        if self._active.get(copy_id) != member_id:
            raise ReservationError("not your reservation")
        del self._active[copy_id]
        self._blocked.add(copy_id)  # defect: a cancelled copy can never be reserved again

    def active(self) -> dict[str, str]:
        return dict(self._active)

