"""Testbench for the reservation service; one test per case id (TC-001..TC-003)."""
import pytest

from reservation import ReservationError, ReservationService


def test_tc_001_reserve_free_copy():
    s = ReservationService()
    s.reserve("c1", "m1")
    assert s.active() == {"c1": "m1"}


def test_tc_002_conflict_on_reserved_copy():
    s = ReservationService()
    s.reserve("c1", "m1")
    with pytest.raises(ReservationError):
        s.reserve("c1", "m2")


def test_tc_003_cancel_frees_copy():
    s = ReservationService()
    s.reserve("c1", "m1")
    s.cancel("c1", "m1")
    s.reserve("c1", "m2")
    assert s.active() == {"c1": "m2"}


def test_tc_004_empty_member_rejected():
    s = ReservationService()
    with pytest.raises(ReservationError):
        s.reserve("c1", "")
    assert s.active() == {}
